# ----------------------------------------------------------------------
# From Google Gemini:
# set of canonical keyphrases for SDG 17 derived from the UN DESA targets and the STRINGS/Auckland taxonomies, formatted ready for Python regex matching:
SDG17_PATTERNS = [
    # 17.1 - 17.5: Finance, ODA, Investment, and Debt
    r"\bofficial development assistance\b",
    r"\bdevelopment assistance committee\b",
    r"\bforeign direct investment\b.*?\b(developing (nations|countries)|least developed countries)\b",
    r"\bdomestic resource mobilization\b",
    r"\bdebt (sustainability|relief|restructuring|distress)\b.*?\b(developing|low-income)\b",
    r"\bconcessional (loans|financing)\b",
    r"\bblended finance\b.*?\bsustainab\b",

    # 17.6 - 17.8: Technology Transfer & Capacity Building
    r"\btechnology transfer\b.*?\b(developing countries|least developed|global south)\b",
    r"\btechnology facilitation mechanism\b",
    r"\btechnology bank for (the )?least developed countries\b",
    r"\b(north-south|south-south|triangular) (cooperation|collaboration|partnership)\b",
    r"\bscience, technology and innovation (capacity|cooperation|partnership)\b",
    r"\bcapacity(-|\s+)building\b.*?\b(least developed|developing nations|global south)\b",

    # 17.9 - 17.12: Trade & Multilateral Governance
    r"\buniversal(,| )? rules-based(,| )? open(,| )? (non-discriminatory )?multilateral trading system\b",
    r"\bworld trade organization\b.*?\b(doha|least developed|developing)\b",
    r"\bduty-free and quota-free market access\b",
    r"\bpreferential rules of origin\b",

    # 17.13 - 17.15: Systemic Issues & Policy Coherence
    r"\bpolicy coherence for sustainable development\b",
    r"\bmacroeconomic stability\b.*?\bsustainable development\b",
    r"\bmulti-stakeholder partnership(s)?\b.*?\bsustainable development goal\b",

    # 17.18 - 17.19: Data, Monitoring, and Metrics
    r"\bstatistical capacity(-|\s+)building\b",
    r"\bsustainable development goal(s)? indicator(s)?\b",
    r"\bdata disaggregation\b.*?\b(vulnerable|income|gender|age)\b",
    r"\bmeasurements of progress on sustainable development\b",
    r"\bgross domestic product\b.*?\bbeyond gdp\b",
]

